/** No external scripts, analytics, fonts, automatic provider calls or browser API keys. */
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let w = C.freshWorkspace(window.ESSENTIEL_LANG || (new URLSearchParams(location.search).get('lang')==='en'?'en':'fr'));
const ui = { route:'today', tab:'tasks', bucket:'all', status:'open', domain:'all', space:'', search:'', sort:'due', moneyTab:'transactions', listKind:'shopping', noteKind:'all', month:C.localDay().slice(0,7), config:{configured:false,model:'jev-1.13.0'}, persist:false, busy:false, stop:false, menu:false, undo:[], labDraft:null, labPreset:'attention', lastRun:'', restoreError:'', sending:0, epoch:0 };
let toastTimer, confirmHandler, deferredImport;
let connectedModule=null,connectedLoading=null;
const connectedRoutes={'connected-inbox':'inbox','connected-calendar':'calendar','connected-tasks':'tasks','connected-files':'files','connected-actions':'actions',connections:'connections'};
function connectedLabel(route){return ({'connected-inbox':L('Courriels','Mail'),'connected-calendar':L('Calendriers connectés','Connected calendars'),'connected-tasks':L('Tâches connectées','Connected tasks'),'connected-files':L('Documents connectés','Connected documents'),'connected-actions':L('Actions et preuves','Actions and receipts'),connections:L('Connexions','Connections'),inbox:L('Sources ajoutées','Added sources'),planner:L('Tâches et agenda locaux','Local tasks and planner')})[route]||T(route);}
function routeHash(route){return route==='inbox'?'sources':route;}
function readRoute(){
  const hash=location.hash.slice(1),params=new URLSearchParams(location.search);
  if(params.has('connected')||params.has('connection_error'))return 'connections';
  if(hash==='sources')return 'inbox';
  if(['inbox','calendar','tasks','files','actions'].includes(hash)&&location.pathname!=='/workspace')return 'connected-'+hash;
  return [...Object.keys(connectedRoutes),'today','inbox','planner','spaces','money','lists','decisions','notebook','lab','settings'].includes(hash)?hash:'today';
}
function mountConnections(){
  if(!connectedRoutes[ui.route]){connectedModule?.hideConnected();return;}
  if(window.ESSENTIEL_PREVIEW){$('connectedHost').innerHTML='<p>'+L('Les connexions nécessitent le serveur local. Cet aperçu n’accède à aucun compte.','Connections require the local server. This preview accesses no account.')+'</p>';return;}
  connectedLoading??=import('./connected.js').then(module=>connectedModule=module);
  connectedLoading.then(module=>{if(connectedRoutes[ui.route])module.mountConnected({route:connectedRoutes[ui.route],language:w.lang,theme:w.theme});}).catch(e=>{if($('connectedHost'))$('connectedHost').textContent=e.message;});
}
function isConnectedEvent(event){return Boolean(event.target.closest?.('#connectedHost, #connectedOverlays'));}

const L = (fr,en) => w.lang === 'fr' ? fr : en;
const T = key => UI[key]?.[w.lang] || key;
