const money = (minor,currency=w.currency) => new Intl.NumberFormat(w.lang==='fr'?'fr-CA':'en-CA',{style:'currency',currency}).format(minor/100);
const domainLabel = id => DOMAINS.find(d=>d.id===id)?.title[w.lang] || id;
const isDemo = x => x.synthetic || x.mode === 'demo';
